import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";
import { Button, Cursor, Docs, Exam, Fan, Material } from "./LorranEja7";

// DELTA CIDADE JARDIM (Lorran) · vídeo 3, versão no estilo da referência que a cliente mandou (House Cleaning):
// frase escrita no alto palavra por palavra com a palavra-chave grifada, um desenho no meio que troca a cada frase,
// cor de fundo virando a cada batida (claro / verde / verde-escuro), logo fixo embaixo, preço rolando na abertura.
// Abertura nova pedida: "R$ 150 por mês. É isso que você investe para concluir o Ensino Médio!" (gravação à parte,
// src/voz-eja7-abertura.wav); o resto é a narração antiga sem silêncios longos e 10% mais rápida (src/voz-eja7-resto-r2.wav).
// Tempos: abertura em segundos do vídeo; resto = OPEN + tempo na voz acelerada (edit/transcripts/voz-eja7-resto-r1.json).

const { fontFamily: F } = loadMontserrat("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FI } = loadMontserrat("italic", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });

export const LR_FPS = 30;
const LEAD = 0.15;
// duração da frase de abertura (atualizar quando a gravação chegar) + 0,25 s de respiro
export const OPEN = 5.4;
const REST = 47.03; // v2: voz-eja7-resto-r2.wav (o v1 cortou fala em "sete" e em "cento e cinquenta reais")
export const LR_FRAMES = Math.round((LEAD + OPEN + REST + 1.3) * LR_FPS);

const GREEN = "#0A6842";
const DEEP = "#053D27";
const LEAF = "#5BAA3C";
const LIME = "#B9E27E";
const INK = "#13261C";
const CREAM = "#F3F5EC";
const WHITE = "#FFFFFF";
const RED = "#D4513A";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 13, stiffness = 200) =>
  spring({ frame: Math.round((t - a) * LR_FPS), fps: LR_FPS, config: { damping, stiffness } });
// tempo na voz acelerada (tempos do r1, já usados nas cenas) -> tempo do vídeo. v2: no r2 dois trechos com fala deixaram
// de ser cortados: antes do "sete" (+0,16 s) e o "cinquenta reais" (+1,21 s a partir de "Você não precisa")
const R = (r: number) => OPEN + r + (r >= 32.5 ? 1.21 : r >= 30.95 ? 0.16 : 0);

type Bg = "cream" | "green" | "deep" | "lime";
const BG: Record<Bg, string> = { cream: CREAM, green: GREEN, deep: DEEP, lime: LIME };
const ink = (b: Bg) => (b === "cream" || b === "lime" ? INK : WHITE);

// ───────── legenda no alto: palavra por palavra, chave grifada ─────────
type Wd = [string, number, boolean?];
const Caption: React.FC<{ t: number; bg: Bg; lines: Wd[][]; size?: number }> = ({ t, bg, lines, size = 68 }) => (
  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
    {lines.map((ln, i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.22, height: size * 1.22, color: ink(bg), textAlign: "center", whiteSpace: "nowrap" }}>
        {ln.map(([w, at, hi], j) => {
          // v2: palavra que ainda não foi dita não ocupa espaço (a linha cresce a partir do centro)
          if (t < at - 0.01) return null;
          const q = k(t, at, 0.18);
          const h = hi ? k(t, at + 0.12, 0.3) : 0;
          return (
            <span key={j} style={{ position: "relative", display: "inline-block", margin: "0 0.12em", opacity: q, transform: `translateY(${(1 - q) * 18}px)` }}>
              {hi && <span style={{ position: "absolute", left: "-0.12em", right: "-0.12em", top: "0.12em", bottom: "0.02em", background: bg === "lime" ? WHITE : LIME, transform: `scaleX(${h})`, transformOrigin: "0 50%", zIndex: 0 }} />}
              <span style={{ position: "relative", zIndex: 1, color: hi && h > 0.3 ? INK : undefined }}>{w}</span>
            </span>
          );
        })}
      </div>
    ))}
  </div>
);

// ───────── cena: fundo liso que vira de cor com um soco de escala ─────────
const Beat: React.FC<{ t: number; a: number; b: number; bg: Bg; wipe?: boolean; children: React.ReactNode }> = ({ t, a, b, bg, wipe, children }) => {
  if (t < a || t >= b) return null;
  const punch = 1.05 - 0.05 * k(t, a, 0.35);
  const drift = 1 + 0.05 * lin(t, a, b);
  const clip = wipe ? `circle(${k(t, a, 0.45) * 130}% at 50% 55%)` : "none";
  return (
    <AbsoluteFill style={{ background: BG[bg], clipPath: clip }}>
      <AbsoluteFill style={{ transform: `scale(${(punch * drift).toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// logo fixo embaixo, como o selo da referência
const Badge: React.FC<{ t: number }> = ({ t }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top: 1690, display: "flex", justifyContent: "center", opacity: k(t, 0, 0.3) }}>
    <div style={{ padding: "22px 40px", borderRadius: 28, background: WHITE, boxShadow: "0 14px 40px rgba(0,0,0,0.18)" }}>
      <Img src={staticFile("lorran/logo-verde.png")} style={{ width: 420, display: "block" }} />
    </div>
  </div>
);

const Pop: React.FC<{ t: number; at: number; children: React.ReactNode; from?: number; rot?: number }> = ({ t, at, children, from = 0.4, rot = 0 }) => {
  if (t < at - 0.02) return null;
  const s = sp(t, at, 12, 230);
  return <div style={{ transform: `scale(${from + (1 - from) * s}) rotate(${(1 - s) * rot}deg)`, opacity: Math.min(1, s * 3) }}>{children}</div>;
};
// v2: frase + desenho num bloco só, centrado no espaço acima do selo (sem vão entre o alto e o meio)
const Stack: React.FC<{ gap?: number; children: React.ReactNode }> = ({ gap = 64, children }) => (
  <div style={{ position: "absolute", left: 100, right: 100, top: 70, height: 1570, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap }}>{children}</div>
);
// encaixa no bloco um desenho que foi feito com posição absoluta na tela inteira
const Box: React.FC<{ w: number; h: number; x: number; y: number; zoom?: number; children: React.ReactNode }> = ({ w, h, x, y, zoom = 1, children }) => (
  <div style={{ position: "relative", width: w * zoom, height: h * zoom, flex: "none" }}>
    <div style={{ position: "absolute", left: -x * zoom, top: -y * zoom, width: 1080, height: 1920, transform: `scale(${zoom})`, transformOrigin: "0 0" }}>{children}</div>
  </div>
);

const XMark: React.FC<{ t: number; at: number; size?: number }> = ({ t, at, size = 90 }) => {
  const d = k(t, at, 0.25), e = k(t, at + 0.12, 0.25);
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
      <circle cx={50} cy={50} r={48} fill={RED} opacity={Math.min(1, d * 2)} />
      <path d="M32 32 L68 68" stroke={WHITE} strokeWidth={11} strokeLinecap="round" strokeDasharray={52} strokeDashoffset={52 * (1 - d)} />
      <path d="M68 32 L32 68" stroke={WHITE} strokeWidth={11} strokeLinecap="round" strokeDasharray={52} strokeDashoffset={52 * (1 - e)} />
    </svg>
  );
};
// cartão de oportunidade: cabeçalho, linhas e o requisito "Ensino Médio completo" que barra
const Opp: React.FC<{ t: number; at: number; x: number; title: string; tag: string; dark?: boolean }> = ({ t, at, x, title, tag, dark }) => (
  <Pop t={t} at={at} from={0.6} rot={-6}>
    <div style={{ width: 860, borderRadius: 40, background: dark ? "#0C5A3A" : WHITE, boxShadow: "0 30px 70px rgba(0,0,0,0.3)", overflow: "hidden" }}>
      <div style={{ padding: "26px 40px", background: dark ? LIME : GREEN, fontFamily: F, fontWeight: 800, fontSize: 46, letterSpacing: "0.12em", color: dark ? INK : WHITE }}>{tag}</div>
      <div style={{ padding: "36px 40px 40px" }}>
        <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 92, color: dark ? WHITE : INK, lineHeight: 1 }}>{title}</div>
        {[480, 380].map((w, i) => <div key={i} style={{ marginTop: i ? 18 : 34, width: w, height: 18, borderRadius: 8, background: dark ? "rgba(255,255,255,0.18)" : "#E1E9E3" }} />)}
        <div style={{ marginTop: 34, display: "flex", alignItems: "center", gap: 24, padding: "18px 24px", borderRadius: 22, background: dark ? "rgba(255,255,255,0.08)" : "#F6EDEA" }}>
          <XMark t={t} at={x} size={86} />
          <div style={{ fontFamily: F, fontWeight: 700, fontSize: 48, color: dark ? WHITE : INK, whiteSpace: "nowrap" }}>Exige Ensino Médio</div>
        </div>
      </div>
    </div>
  </Pop>
);

// v2: foto inteira (moldura na proporção da própria foto, sem corte), entra subindo leve e respira devagar
const Photo: React.FC<{ t: number; at: number; b: number; src: string; w: number; ratio: number }> = ({ t, at, b, src, w, ratio }) => {
  if (t < at - 0.02) return null;
  const s = sp(t, at, 16, 140);
  const drift = 1 + 0.035 * lin(t, at, b);
  return (
    <div style={{ width: w, height: w / ratio, flex: "none", opacity: Math.min(1, s * 2.5), transform: `translateY(${(1 - s) * 160}px) scale(${((0.92 + 0.08 * s) * drift).toFixed(4)}) rotate(${(1 - s) * -3}deg)` }}>
      <div style={{ width: "100%", height: "100%", borderRadius: 36, overflow: "hidden", border: `10px solid ${WHITE}`, boxShadow: "0 30px 80px rgba(0,0,0,0.28)", boxSizing: "border-box" }}>
        <Img src={staticFile(`lorran/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
      </div>
    </div>
  );
};

// preço rolando: "R$ 150" com marca-texto e "/mês"
const PriceRoll: React.FC<{ t: number; at: number; dark?: boolean; size?: number }> = ({ t, at, dark, size = 230 }) => {
  const n = Math.round(interpolate(t, [at, at + 0.75], [12, 150], { ...cl, easing: Easing.out(Easing.cubic) }));
  const hl = k(t, at + 0.75, 0.3);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div style={{ position: "relative", padding: "0 30px" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: "38%", bottom: "4%", background: LIME, transform: `scaleX(${hl}) rotate(-1.5deg)`, transformOrigin: "0 50%" }} />
        <span style={{ position: "relative", fontFamily: F, fontWeight: 900, fontSize: size * 0.42, color: dark ? WHITE : INK, verticalAlign: "top" }}>R$ </span>
        <span style={{ position: "relative", display: "inline-block", minWidth: size * 1.62, fontFamily: F, fontWeight: 900, fontSize: size, lineHeight: 1, color: dark ? WHITE : INK, letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums" }}>{n}</span>
      </div>
    </div>
  );
};

export const LorranEja7Ref: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / LR_FPS - LEAD;
  // tempos da abertura (src/voz-eja7-abertura.wav: gravação de 15/10, 10% mais rápida, sem o silêncio inicial e com a pausa após "mês" encurtada)
  const A = { r150: 0.12, mes: 1.4, e: 2.42, investe: 3.16, para: 3.6, ensino: 4.26 };
  const mes = sp(t, A.mes, 11, 230);
  const pill = (txt: React.ReactNode, bg: string, fg: string, size = 64) => (
    <div style={{ padding: "14px 40px 18px", borderRadius: 24, background: bg, fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: size, color: fg, whiteSpace: "nowrap", boxShadow: "0 20px 50px rgba(0,0,0,0.25)" }}>{txt}</div>
  );
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {/* ── abertura nova ── */}
      <Beat t={t} a={-0.2} b={A.e - 0.05} bg="cream">
        <Stack gap={40}>
          <Pop t={t} at={-0.1} from={0.6}><div style={{ padding: "14px 34px", borderRadius: 18, background: GREEN, fontFamily: F, fontWeight: 800, fontSize: 48, color: WHITE }}>EJA · Ensino Médio</div></Pop>
          <PriceRoll t={t} at={A.r150} />
          <div style={{ height: 120 }}>{t > A.mes - 0.05 && <div style={{ padding: "12px 44px", borderRadius: 22, background: INK, fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 90, color: WHITE, transform: `scale(${0.4 + 0.6 * mes}) rotate(-3deg)`, opacity: Math.min(1, mes * 3) }}>/mês</div>}</div>
        </Stack>
      </Beat>
      <Beat t={t} a={A.e - 0.05} b={A.para - 0.05} bg="deep">
        <Stack>
          <Caption t={t} bg="deep" size={72} lines={[[["É", A.e], ["isso", A.e + 0.18], ["que", A.e + 0.4], ["você", A.e + 0.52]], [["investe", A.investe, true]]]} />
          <Pop t={t} at={A.e} from={0.5} rot={-8}>
            <div style={{ padding: "30px 70px 44px", borderRadius: 44, background: GREEN, boxShadow: "0 30px 80px rgba(0,0,0,0.35)", transform: "rotate(-3deg)", display: "flex", flexDirection: "column", alignItems: "center" }}>
              <div><span style={{ fontFamily: F, fontWeight: 900, fontSize: 100, color: LIME, verticalAlign: "top" }}>R$ </span><span style={{ fontFamily: F, fontWeight: 900, fontSize: 250, color: WHITE, letterSpacing: "-0.04em", lineHeight: 1 }}>150</span></div>
              <div style={{ marginTop: 6, padding: "8px 34px", borderRadius: 16, background: WHITE, fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 72, color: INK }}>/mês</div>
            </div>
          </Pop>
        </Stack>
      </Beat>
      <Beat t={t} a={A.para - 0.05} b={OPEN} bg="lime" wipe>
        <Stack>
          <Caption t={t} bg="lime" size={72} lines={[[["para", A.para], ["concluir", A.para + 0.2], ["o", A.para + 0.45]], [["Ensino", A.ensino, true], ["Médio!", A.ensino + 0.3, true]]]} />
          <Pop t={t} at={A.para + 0.1} from={0.4} rot={10}>
            <div style={{ width: 760, height: 520, borderRadius: 34, background: WHITE, boxShadow: "0 30px 80px rgba(3,40,24,0.3)", border: `14px solid ${CREAM}`, outline: `4px solid ${GREEN}`, outlineOffset: -26, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", boxSizing: "border-box" }}>
              <Img src={staticFile("lorran/logo-verde.png")} style={{ width: 460 }} />
              <div style={{ marginTop: 34, fontFamily: F, fontWeight: 800, fontSize: 54, letterSpacing: "0.2em", color: GREEN }}>CERTIFICADO</div>
              {[360, 280].map((w, i) => <div key={i} style={{ marginTop: i ? 16 : 30, width: w, height: 14, borderRadius: 7, background: "#DCE6DE" }} />)}
            </div>
          </Pop>
        </Stack>
      </Beat>

      {/* ── oportunidades perdidas ── */}
      <Beat t={t} a={OPEN} b={R(2.6)} bg="deep">
        <Stack>
          <Caption t={t} bg="deep" lines={[[["Você", R(0.05)], ["provavelmente", R(0.39)]], [["já", R(1.17)], ["perdeu", R(1.29), true], ["alguma", R(1.59)]], [["oportunidade", R(1.93)]]]} />
          <Opp t={t} at={R(0.3)} x={R(1.3)} title="Promoção" tag="OPORTUNIDADE" dark />
        </Stack>
      </Beat>
      <Beat t={t} a={R(2.6)} b={R(3.37)} bg="cream">
        <Stack>
          <Caption t={t} bg="cream" size={72} lines={[[["de", R(2.57)], ["emprego,", R(2.65), true]]]} />
          <Opp t={t} at={R(2.6)} x={R(2.95)} title="Emprego" tag="VAGA ABERTA" />
        </Stack>
      </Beat>
      <Beat t={t} a={R(3.37)} b={R(4.8)} bg="green">
        <Stack>
          <Caption t={t} bg="green" lines={[[["de", R(3.39)], ["fazer", R(3.51)], ["um", R(3.75)]], [["curso", R(3.83), true], ["técnico", R(4.15), true]]]} />
          <Opp t={t} at={R(3.4)} x={R(4.3)} title="Curso técnico" tag="INSCRIÇÕES" dark />
        </Stack>
      </Beat>
      <Beat t={t} a={R(4.8)} b={R(6.85)} bg="cream">
        <Stack>
          <Caption t={t} bg="cream" lines={[[["ou", R(4.82)], ["até", R(4.93)], ["de", R(5.25)], ["participar", R(5.39)]], [["de", R(5.92)], ["um", R(6.02)], ["concurso,", R(6.08), true]]]} />
          <Opp t={t} at={R(4.85)} x={R(6.2)} title="Concurso" tag="EDITAL" />
        </Stack>
      </Beat>
      <Beat t={t} a={R(6.85)} b={R(9.1)} bg="deep" wipe>
        <Stack>
          <Caption t={t} bg="deep" lines={[[["porque", R(6.9)], ["ainda", R(7.16)], ["não", R(7.52)]], [["concluiu", R(7.72)], ["seus", R(8.22), true], ["estudos.", R(8.42), true]]]} />
          <Pop t={t} at={R(6.95)} from={0.6}>
            <div style={{ width: 880, padding: "56px 56px", borderRadius: 40, background: "#0C5A3A", boxSizing: "border-box" }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontFamily: F, fontWeight: 800, fontSize: 62, color: WHITE }}><span>Ensino Médio</span><span style={{ color: LIME }}>{Math.round(58 * k(t, R(7.1), 0.9))}%</span></div>
              <div style={{ marginTop: 30, height: 44, borderRadius: 22, background: "rgba(255,255,255,0.15)", overflow: "hidden" }}>
                <div style={{ width: `${58 * k(t, R(7.1), 0.9)}%`, height: "100%", borderRadius: 22, background: `linear-gradient(90deg, ${LEAF}, ${LIME})`, transform: `translateX(${t > R(8.1) && t < R(8.6) ? Math.sin((t - R(8.1)) * 50) * 8 : 0}px)` }} />
              </div>
            </div>
          </Pop>
        </Stack>
      </Beat>

      {/* ── como funciona aqui: fachada inteira ── */}
      <Beat t={t} a={R(9.1)} b={R(12.3)} bg="cream">
        <Stack gap={50}>
          <Caption t={t} bg="cream" size={56} lines={[[["Mas", R(9.18)], ["olha", R(9.46)], ["só", R(9.8)], ["como", R(9.98)], ["funciona", R(10.2)]], [["aqui", R(10.66)], ["na", R(10.94)], ["Delta", R(11.14), true], ["Cidade", R(11.46), true], ["Jardim", R(11.78), true]]]} />
          <Photo t={t} at={R(9.2)} b={R(12.3)} src="x-fachada.jpg" w={760} ratio={1024 / 1536} />
        </Stack>
      </Beat>

      {/* ── passo 1: material ── */}
      <Beat t={t} a={R(12.3)} b={R(16.25)} bg="lime" wipe>
        <Stack gap={40}>
          <Caption t={t} bg="lime" lines={[[["Primeiro,", R(12.38)], ["você", R(13.06)], ["recebe", R(13.28)]], [["o", R(13.66)], ["material", R(13.7), true], ["de", R(14.1), true], ["estudo", R(14.18), true]]]} />
          <Box w={800} h={760} x={140} y={520}><Material t={t - R(13.28) + 23.53} /></Box>
          <Caption t={t} bg="lime" size={48} lines={[[["para", R(14.58)], ["se", R(14.78)], ["preparar", R(14.94)], ["para", R(15.46)], ["a", R(15.6)], ["avaliação", R(15.64)]]]} />
        </Stack>
      </Beat>

      {/* ── passo 2: avaliação ── */}
      <Beat t={t} a={R(16.25)} b={R(18.45)} bg="deep">
        <Stack>
          <Caption t={t} bg="deep" lines={[[["Depois,", R(16.3)], ["realiza", R(17.02)]], [["sua", R(17.61)], ["avaliação,", R(17.75), true]]]} />
          <Box w={740} h={820} x={170} y={520}><Exam t={t - R(16.3) + 27.0} /></Box>
        </Stack>
      </Beat>

      {/* ── passo 3: documentos (pedido da cliente) ── */}
      <Beat t={t} a={R(18.45)} b={R(22.8)} bg="cream" wipe>
        <Stack gap={44}>
          <Caption t={t} bg="cream" size={58} lines={[[["apresenta", R(18.49)], ["a", R(19.07)]], [["documentação", R(19.11), true], ["necessária", R(19.71), true]]]} />
          <Box w={840} h={1180} x={120} y={440} zoom={0.9}><Docs t={t - R(18.7) + 30.2} /></Box>
        </Stack>
      </Beat>

      {/* ── passo 4: certificado (formanda real da Delta, foto inteira) ── */}
      <Beat t={t} a={R(22.8)} b={R(25.9)} bg="green">
        <Stack gap={50}>
          <Caption t={t} bg="green" size={56} lines={[[["recebe", R(22.83)], ["seu", R(23.29)], ["certificado", R(23.49), true]], [["de", R(24.19)], ["conclusão", R(24.37)], ["do", R(24.99)], ["Ensino", R(25.09)], ["Médio", R(25.39)]]]} />
          <Photo t={t} at={R(22.85)} b={R(25.9)} src="f-delta1.jpg" w={700} ratio={1074 / 1740} />
        </Stack>
      </Beat>
      <Beat t={t} a={R(25.9)} b={R(29.0)} bg="deep" wipe>
        <Stack gap={56}>
          <Caption t={t} bg="deep" size={58} lines={[[["reconhecido", R(25.93), true], ["e", R(26.7)], ["válido", R(26.84), true]], [["em", R(27.3)], ["todo", R(27.55)], ["o", R(27.82)], ["território", R(27.88)], ["nacional.", R(28.36)]]]} />
          <Pop t={t} at={R(26.0)} from={2.2} rot={-30}>
            <svg width={500} height={500} viewBox="0 0 100 100" style={{ display: "block" }}>
              {Array.from({ length: 20 }).map((_, i) => <circle key={i} cx={50 + 44 * Math.cos((i / 20) * Math.PI * 2)} cy={50 + 44 * Math.sin((i / 20) * Math.PI * 2)} r={7} fill={LEAF} />)}
              <circle cx={50} cy={50} r={44} fill={LIME} />
