import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// DELTA CIDADE JARDIM (Lorran) · vídeo 3: EJA Ensino Médio em 7 parcelas de R$ 150. Motion vertical de 63 s sobre a
// locução (ElevenLabs, voz Roberta, 61,5 s, entra em 0,15 s). Mesma identidade dos outros dois (verde, Montserrat itálica
// pesada), linguagem própria: preço como etiqueta, passo a passo numerado 1–4, lista de documentos em folha de caderno
// (arte da cliente), fachada da unidade em "como funciona aqui". Pedidos da cliente por áudio: documentos na tela em
// "documentação necessária" e a fachada em "olha só como funciona aqui na Delta Cidade Jardim".
// Tempos = palavra na voz ((arquivo do cliente)).

const { fontFamily: F } = loadMontserrat("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FI } = loadMontserrat("italic", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });

export const L7_FPS = 30;
const LEAD = 0.15;
export const L7_FRAMES = Math.round(63 * L7_FPS);

const GREEN = "#0A6842";
const DEEP = "#053D27";
const NIGHT = "#03271A";
const LEAF = "#5BAA3C";
const LIME = "#B9E27E";
const INK = "#13261C";
const PAPER = "#F4F8F3";
const WHITE = "#FFFFFF";
const GRAY = "#9AA8A0";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * L7_FPS), fps: L7_FPS, config: { damping, stiffness } });

// ───────── texto ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; weight?: number; shadow?: boolean }> = ({ t, words, size = 56, color = WHITE, weight = 600, shadow }) => (
  <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.18, color, textAlign: "center", whiteSpace: "nowrap", textShadow: shadow ? "0 4px 26px rgba(0,25,15,0.65)" : undefined }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.26);
      return <span key={i} style={{ display: "inline-block", margin: "0 0.12em", opacity: q, transform: `scale(${0.6 + 0.4 * q})`, filter: `blur(${(1 - q) * 6}px)` }}>{w}</span>;
    })}
  </div>
);
// destaque: carimba (vem grande e assenta)
const Big: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; color?: string; shadow?: boolean }> = ({ t, at, children, size = 110, color = WHITE, shadow }) => {
  const s = sp(t, at, 12, 220);
  return (
    <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: size, lineHeight: 1.04, letterSpacing: "-0.025em", textAlign: "center", whiteSpace: "nowrap", padding: "0 0.08em 0.05em", color,
      opacity: Math.min(1, s * 3), transform: `scale(${1.6 - 0.6 * s})`, textShadow: shadow ? "0 6px 30px rgba(0,25,15,0.6)" : undefined }}>{children}</div>
  );
};
const Block: React.FC<{ t: number; top: number; at: number; out?: number; gap?: number; children: React.ReactNode }> = ({ t, top, at, out, gap = 10, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.14)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.12);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: 1 - o, transform: `scale(${1 - o * 0.08})` }}>{children}</div>
  );
};

// ───────── fundos, fotos, transições ─────────
const Green: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 60% at 50% 45%, #0F7C4F 0%, ${GREEN} 50%, ${DEEP} 100%)` }} />;
const Night: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 90% 60% at 50% 42%, #08452C 0%, ${DEEP} 55%, ${NIGHT} 100%)` }} />;
const Paper: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 60% at 50% 45%, #FFFFFF 0%, ${PAPER} 60%, #E6EFE4 100%)` }} />;
const Photo: React.FC<{ t: number; src: string; a: number; b: number; z0: number; z1: number; ox?: number; oy?: number; pos?: string }> = ({ t, src, a, b, z0, z1, ox = 50, oy = 50, pos = "50% 50%" }) => {
  const e = 0.3 * k(t, a, 0.6) + 0.7 * lin(t, a, b);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: DEEP }}>
      <AbsoluteFill style={{ transform: `scale(${(z0 + (z1 - z0) * e).toFixed(4)})`, transformOrigin: `${ox}% ${oy}%` }}>
        <Img src={staticFile(`lorran/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos }} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
const Scrim: React.FC<{ top?: boolean }> = ({ top }) => (
  <AbsoluteFill style={{ background: top
    ? "linear-gradient(180deg, rgba(3,30,19,0.9) 0%, rgba(3,30,19,0.55) 28%, rgba(3,30,19,0) 48%)"
    : "linear-gradient(180deg, rgba(3,30,19,0) 44%, rgba(3,30,19,0.6) 66%, rgba(3,30,19,0.92) 100%)" }} />
);

type Tr = "none" | "band" | "slideL" | "slideUp" | "zoom" | "circle" | "flip" | "iris";
const TD = 0.4;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; cam?: [number, number]; children: React.ReactNode }> = ({ t, a, b, tr, cam = [1, 1.08], children }) => {
  if (t < a || t > b + TD) return null;
  const q = tr === "none" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "band") clip = `polygon(0 ${(1 - q) * 100}%, 100% ${(1 - q) * 100 - 20 * (1 - q)}%, 100% 100%, 0 100%)`;
  if (tr === "slideL") tf = `translateX(${(1 - q) * 100}%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.3 - 0.3 * q})`; op = Math.min(1, q * 1.7); }
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 50%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 50}% ${(1 - q) * 50}% round ${(1 - q) * 200}px)`;
  if (tr === "flip") { tf = `perspective(2200px) rotateX(${(1 - q) * -80}deg)`; op = q > 0.02 ? 1 : 0; }
  const p = lin(t, a, b + TD);
  const z = cam[0] + (cam[1] - cam[0]) * p;
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `translateY(${(-40 * p).toFixed(1)}px) scale(${z.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── peças ─────────
// etiqueta de preço: "7x" + "R$ 150"
const Price: React.FC<{ t: number; at7: number; atR: number; scale?: number }> = ({ t, at7, atR, scale = 1 }) => {
  const a = sp(t, at7, 11, 230), b = sp(t, atR, 11, 230);
  const n = Math.round(150 * k(t, atR, 0.7));
  const shine = lin(t, atR + 0.75, atR + 1.35);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", transform: `scale(${scale})` }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 18, opacity: Math.min(1, a * 3), transform: `scale(${1.8 - 0.8 * a}) rotate(${(1 - a) * -8}deg)` }}>
        <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 300, lineHeight: 0.95, color: WHITE, letterSpacing: "-0.04em" }}>7</span>
        <span style={{ fontFamily: F, fontWeight: 800, fontSize: 84, color: LIME }}>parcelas de</span>
      </div>
      <div style={{ position: "relative", overflow: "hidden", marginTop: 18, padding: "18px 56px 28px", borderRadius: 40, background: WHITE, boxShadow: "0 30px 80px rgba(0,0,0,0.35)", opacity: Math.min(1, b * 3), transform: `scale(${0.4 + 0.6 * b}) rotate(${(1 - b) * 10 - 2}deg)` }}>
        <span style={{ fontFamily: F, fontWeight: 800, fontSize: 90, color: GREEN, verticalAlign: "top" }}>R$ </span>
        <span style={{ display: "inline-block", minWidth: 330, textAlign: "left", fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 220, lineHeight: 1, color: GREEN, letterSpacing: "-0.03em", fontVariantNumeric: "tabular-nums" }}>{n}</span>
        {shine > 0 && shine < 1 && <div style={{ position: "absolute", top: -40, bottom: -40, width: 120, left: `${-20 + 140 * shine}%`, background: "linear-gradient(90deg, rgba(185,226,126,0), rgba(185,226,126,0.55), rgba(185,226,126,0))", transform: "skewX(-20deg)" }} />}
      </div>
    </div>
  );
};

// v3: abertura com as 7 parcelas como cartões distribuídos em leque
export const Fan: React.FC<{ t: number }> = ({ t }) => {
  const spread = 0.78 + 0.22 * k(t, 1.3, 2.0);
  return (
    <>
      {Array.from({ length: 7 }).map((_, i) => {
        const at = 0.3 + i * 0.13;
        if (t < at - 0.02) return null;
        const s = sp(t, at, 15, 210);
        const ang = (i - 3) * 8 * spread * s + (1 - s) * (i - 3) * 30;
        const lift = i === 6 ? -30 * k(t, 1.67, 0.4) : 0;
        return (
          <div key={i} style={{ position: "absolute", left: 405, top: 660, width: 270, height: 400, transformOrigin: "50% 210%", transform: `translateY(${(1 - s) * 1100 + lift}px) rotate(${ang.toFixed(2)}deg)`, opacity: Math.min(1, s * 3) }}>
            <div style={{ width: "100%", height: "100%", borderRadius: 30, background: WHITE, boxShadow: "0 24px 60px rgba(0,0,0,0.35)", overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center" }}>
              <div style={{ width: "100%", height: 96, background: i % 2 ? LEAF : GREEN, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 34, letterSpacing: "0.12em", color: WHITE }}>{i + 1}/7</div>
              <div style={{ marginTop: 56, fontFamily: F, fontWeight: 800, fontSize: 40, color: GREEN }}>R$</div>
              <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 120, lineHeight: 1, color: GREEN, letterSpacing: "-0.03em" }}>150</div>
              {[170, 130].map((w, j) => <div key={j} style={{ marginTop: j ? 14 : 34, width: w, height: 12, borderRadius: 6, background: "#E1E9E3" }} />)}
            </div>
          </div>
        );
      })}
    </>
  );
};

export const Check: React.FC<{ t: number; at: number; size?: number; bg?: string }> = ({ t, at, size = 64, bg = LEAF }) => {
  const s = sp(t, at, 11, 240);
  const d = k(t, at + 0.08, 0.28);
