export const Cursor: React.FC<{ t: number; at: number; x: number; y: number }> = ({ t, at, x, y }) => {
  const m = k(t, at - 0.45, 0.42);
  const press = t > at && t < at + 0.16 ? 0.85 : 1;
  // v4: depois do clique o cursor sai, para não ficar em cima do texto do botão
  const gone = k(t, at + 0.3, 0.35);
  return (
    <div style={{ position: "absolute", left: x + 240 * (1 - m) + 160 * gone, top: y + 320 * (1 - m) + 220 * gone, opacity: lin(t, at - 0.45, at - 0.3) * (1 - gone), transform: `scale(${press})`, transformOrigin: "20% 10%" }}>
